def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(out),len(out[0])
    pts={v:[] for v in (1,2,3,6)}
    for r in range(h):
        for c in range(w):
            if grid[r][c] in pts: pts[grid[r][c]].append((r,c))
    def put(r,c,v):
        if 0<=r<h and 0<=c<w: out[r][c]=v
    # fixed colored motifs
    for r,c in pts[1]:
        put(r,c+1,5); put(r,c+2,5); put(r-1,c+2,1)
    for r,c in pts[2]:
        for k in range(1,4): put(r,c-k,5)
        put(r,c-4,2)
    for r,c in pts[3]:
        put(r+1,c,5); put(r+2,c,5); put(r+3,c,3)
    for r,c in pts[6]:
        for k in range(1,6): put(r-k,c,5)
        put(r-6,c,6)
    # intersections of the horizontal 2 arm and vertical 3/6 arms
    for r,c in pts[2]:
        for color,dr in ((3,3),(6,-6)):
            for vr,vc in pts[color]:
                # vertical colored motif range, including its source
                end=vr+dr
                if min(vr,end)<=r<=max(vr,end) and c>=vc-4 and c<=vc+4: # correct cross is at horizontal arm position and vertical column
                    # horizontal line is centered on source2? intersect at c of vertical marker
                    x=vc
                    if c-4<=x<=c:
                        put(r,x,4)
                        for n in range(1,h): put(r+n,x-n,4)
    return out

